// ============================================================================
// 5. ViewModel & UI State Management
// ============================================================================
data class LauncherUiState(
    val activeTopTab: TopNavTab = TopNavTab.MY_GAMES,
        val selectedPlatform: ConsolePlatform = ConsolePlatform.PSP,
            val allGames: List<GameItem> = emptyList(),
                val searchQuery: String = "",
                    val isSearchDialogVisible: Boolean = false,
                        val isOptionsDialogVisible: Boolean = false,
                            val isScanningOrScraping: Boolean = false,
                                val statusBannerMessage: String? = null,
                                    val focusedGameIndex: Int = 0
                                    ) {
                                        val filteredGames: List<GameItem>
                                                get() = allGames.filter { game ->
                                                            game.consoleId == selectedPlatform.id &&
                                                                            (searchQuery.isBlank() || game.title.contains(searchQuery, ignoreCase = true) || game.genre.contains(searchQuery, ignoreCase = true))
                                                                                    }

                                                                                        val focusedGame: GameItem?
                                                                                                get() = filteredGames.getOrNull(focusedGameIndex.coerceIn(0, (filteredGames.size - 1).coerceAtLeast(0)))
                                                                                                }

                                                                                                class LauncherViewModel(
                                                                                                    private val romScanner: RomScannerManager = RomScannerManager(),
                                                                                                        private val scraperService: MetadataScraperService = MetadataScraperService()
                                                                                                        ) : ViewModel() {

                                                                                                            private val _uiState = MutableStateFlow(LauncherUiState(allGames = SampleGameCatalog.createInitialLibrary()))
                                                                                                                val uiState: StateFlow<LauncherUiState> = _uiState.asStateFlow()

                                                                                                                    fun selectTopTab(tab: TopNavTab) = _uiState.update { it.copy(activeTopTab = tab) }

                                                                                                                        fun selectPlatform(platform: ConsolePlatform) = _uiState.update {
                                                                                                                                it.copy(selectedPlatform = platform, focusedGameIndex = 0, statusBannerMessage = null)
                                                                                                                                    }

                                                                                                                                        fun cyclePlatform(direction: Int) {
                                                                                                                                                val platforms = ConsolePlatform.entries
                                                                                                                                                        val nextIdx = (platforms.indexOf(_uiState.value.selectedPlatform) + direction + platforms.size) % platforms.size
                                                                                                                                                                selectPlatform(platforms[nextIdx])
                                                                                                                                                                    }

                                                                                                                                                                        fun moveGameFocus(delta: Int) = _uiState.update { state ->
                                                                                                                                                                                val games = state.filteredGames
                                                                                                                                                                                        if (games.isEmpty()) state.copy(focusedGameIndex = 0)
                                                                                                                                                                                                else state.copy(focusedGameIndex = (state.focusedGameIndex + delta).coerceIn(0, games.lastIndex))
                                                                                                                                                                                                    }

                                                                                                                                                                                                        fun setFocusedGameIndex(index: Int) = _uiState.update { state ->
                                                                                                                                                                                                                state.copy(focusedGameIndex = index.coerceIn(0, (state.filteredGames.size - 1).coerceAtLeast(0)))
                                                                                                                                                                                                                    }

                                                                                                                                                                                                                        fun toggleSearchDialog(visible: Boolean) = _uiState.update { it.copy(isSearchDialogVisible = visible) }
                                                                                                                                                                                                                            fun updateSearchQuery(query: String) = _uiState.update { it.copy(searchQuery = query, focusedGameIndex = 0) }
                                                                                                                                                                                                                            fun toggleOptionsMenu(visible: Boolean) = _uiState.update { it.copy(isOptionsDialogVisible = visible) }

                                                                                                                                                                                                                                fun applyCustomCoverToFocusedGame(customImageUri: Uri) {
                                                                                                                                                                                                                                        val current = _uiState.value.focusedGame ?: return
                                                                                                                                                                                                                                                _uiState.update { state ->
                                                                                                                                                                                                                                                            state.copy(
                                                                                                                                                                                                                                                                            allGames = state.allGames.map { if (it.id == current.id) it.copy(customCoverUri = customImageUri.toString()) else it },
                                                                                                                                                                                                                                                                                            statusBannerMessage = "ตั้งค่าหน้าปก Custom Cover สำหรับ '${current.title}' เรียบร้อยแล้ว"
                                                                                                                                                                                                                                                                                                        )
                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                        fun scrapeFocusedGameMetadata() {
                                                                                                                                                                                                                                                                                                                                val target = _uiState.value.focusedGame ?: return
                                                                                                                                                                                                                                                                                                                                        viewModelScope.launch {
                                                                                                                                                                                                                                                                                                                                                    _uiState.update { it.copy(isScanningOrScraping = true, statusBannerMessage = "กำลังดึงข้อมูลปกและ Fanart ของ '${target.title}'...") }
                                                                                                                                                                                                                                                                                                                                                                val scraped = scraperService.scrapeGameMetadata(target)
                                                                                                                                                                                                                                                                                                                                                                            _uiState.update { state ->
                                                                                                                                                                                                                                                                                                                                                                                            state.copy(
                                                                                                                                                                                                                                                                                                                                                                                                                allGames = state.allGames.map {
                                                                                                                                                                                                                                                                                                                                                                                                                                        if (it.id == target.id) it.copy(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    title = scraped.cleanTitle,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                coverUrl = scraped.boxartCoverUrl,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fanartUrl = scraped.fanartBackgroundUrl,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        description = scraped.overviewDescription,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    releaseYear = scraped.releaseYear,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                developer = scraped.developerName,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            genre = scraped.genreName
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) else it
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            isScanningOrScraping = false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                statusBannerMessage = "ดึงข้อมูล Metadata และ Fanart ของ '${scraped.cleanTitle}' สำเร็จ!"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fun scanLocalRomFolder(rootPath: String = "/storage/emulated/0/ROMs") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    viewModelScope.launch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                _uiState.update { it.copy(isScanningOrScraping = true, statusBannerMessage = "กำลังสแกนโฟลเดอร์ ROMs ที่ $rootPath ...") }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            val scanned = romScanner.scanDirectoryForRoms(File(rootPath))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        delay(400)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    _uiState.update { state ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    val merged = if (scanned.isNotEmpty()) (state.allGames + scanned).distinctBy { it.romFilePath } else state.allGames
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    state.copy(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        allGames = merged,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            isScanningOrScraping = false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                statusBannerMessage = if (scanned.isNotEmpty()) "พบเกมใหม่ ${scanned.size} เกม" else "สแกนเสร็จสิ้น (แสดงคลังเกมเริ่มต้น ${merged.size} เกม)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 6. หน้าจอหลัก Console Dashboard + พื้นหลัง Dynamic Fanart + Top Navigation Bar
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        @Composable
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fun UnifiedEmulatorLauncherApp(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            viewModel: LauncherViewModel = androidx.lifecycle.viewmodel.compose.viewModel()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                val context = LocalContext.current
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    val uiState by viewModel.uiState.collectAsState()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        val intentLauncher = remember(context) { EmulatorIntentLauncher(context) }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            val rootFocusRequester = remember { FocusRequester() }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                val carouselListState = rememberLazyListState()

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    val customCoverPicker = rememberLauncherForActivityResult(ActivityResultContracts.PickVisualMedia()) { uri: Uri? ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (uri != null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        try { context.contentResolver.takePersistableUriPermission(uri, Intent.FLAG_GRANT_READ_URI_PERMISSION) } catch (_: Exception) {}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    viewModel.applyCustomCoverToFocusedGame(uri)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    LaunchedEffect(uiState.focusedGameIndex, uiState.selectedPlatform) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (uiState.filteredGames.isNotEmpty()) carouselListState.animateScrollToItem(uiState.focusedGameIndex)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    LaunchedEffect(Unit) { rootFocusRequester.requestFocus() }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        val launchFocusedGame: () -> Unit = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                uiState.focusedGame?.let { game ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            when (val res = intentLauncher.launchGame(game, uiState.selectedPlatform)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            is EmulatorIntentLauncher.LaunchResult.Success ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Toast.makeText(context, "กำลังเปิด ${game.title}", Toast.LENGTH_SHORT).show()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                is EmulatorIntentLauncher.LaunchResult.EmulatorNotInstalled ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Toast.makeText(context, "ส่ง Intent '${game.romFilePath}' -> กรุณาติดตั้งแอป ${res.packageName} (${res.platformName})", Toast.LENGTH_LONG).show()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    is EmulatorIntentLauncher.LaunchResult.Error ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Toast.makeText(context, res.message, Toast.LENGTH_LONG).show()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Box(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            modifier = Modifier
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .fillMaxSize()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .background(Color(0xFF070A12))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .focusRequester(rootFocusRequester)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .focusable()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .onPreviewKeyEvent { ev ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (ev.type != KeyEventType.KeyDown) return@onPreviewKeyEvent false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            when (ev.nativeKeyEvent.keyCode) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                AndroidKeyEvent.KEYCODE_DPAD_LEFT -> { viewModel.moveGameFocus(-1); true }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    AndroidKeyEvent.KEYCODE_DPAD_RIGHT -> { viewModel.moveGameFocus(1); true }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AndroidKeyEvent.KEYCODE_BUTTON_L1, AndroidKeyEvent.KEYCODE_PAGE_UP -> { viewModel.cyclePlatform(-1); true }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            AndroidKeyEvent.KEYCODE_BUTTON_R1, AndroidKeyEvent.KEYCODE_PAGE_DOWN -> { viewModel.cyclePlatform(1); true }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                AndroidKeyEvent.KEYCODE_BUTTON_A, AndroidKeyEvent.KEYCODE_DPAD_CENTER, AndroidKeyEvent.KEYCODE_ENTER -> { launchFocusedGame(); true }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    AndroidKeyEvent.KEYCODE_BUTTON_Y -> { viewModel.toggleSearchDialog(!uiState.isSearchDialogVisible); true }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AndroidKeyEvent.KEYCODE_BUTTON_X -> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                customCoverPicker.launch(PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                AndroidKeyEvent.KEYCODE_BUTTON_START, AndroidKeyEvent.KEYCODE_MENU -> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        viewModel.toggleOptionsMenu(!uiState.isOptionsDialogVisible)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else -> false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                DynamicFanartBackground(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fanartUrl = uiState.focusedGame?.fanartUrl ?: uiState.focusedGame?.effectiveCoverModel,
